svg.script:
{
  "metadata": {"title": "DevOps Architecture", "projectName": "Food Delivery System", "description": "Complete DevOps infrastructure and toolchain", "version": "1.0", "mode": "light"},
  "config": {"layout": {"canvasWidth": 1920, "canvasHeight": 1080}, "styling": {"mode": "light", "canvasColor": "#FFFFFF", "fillColor": "#E5E5E5", "strokeColor": "#1A1A1A"}},
  "data": {
    "layers": [
      {"id": "plan", "name": "Plan", "x": 200, "y": 250, "width": 380, "height": 600},
      {"id": "develop", "name": "Develop", "x": 640, "y": 250, "width": 380, "height": 600},
      {"id": "operate", "name": "Operate", "x": 1080, "y": 250, "width": 380, "height": 600},
      {"id": "monitor", "name": "Monitor", "x": 1520, "y": 250, "width": 380, "height": 600}
    ]
  }
}

(function() {
  const dataElement = document.currentScript.closest('svg').querySelector('#devops-architecture-data');
  if (!dataElement) return;
  try {
    const data = JSON.parse(dataElement.textContent);
    console.log('[DevOps Architecture Data] Loaded:', data.metadata.title);
  } catch (e) {
    console.error('[DevOps Architecture] Invalid JSON:', e.message);
  }
})();
